export interface GeoBbox {
  south: number;
  west: number;
  north: number;
  east: number;
}

export interface MapMetadata {
  city: string;
  source: string;
  license: string;
  generatedAt: string;
  bbox: GeoBbox;
  viewBox: { width: number; height: number };
  projection: {
    type: string;
    minMercY: number;
    maxMercY: number;
    description: string;
  };
}

export const SANTA_MARIA_METADATA: MapMetadata = {
  "city": "Santa Maria, RS, Brasil",
  "source": "OpenStreetMap contributors",
  "license": "ODbL (https://www.openstreetmap.org/copyright)",
  "generatedAt": "2026-10-04T19:45:23.371Z",
  "bbox": {
    "south": -29.715,
    "west": -53.84,
    "north": -29.665,
    "east": -53.775
  },
  "viewBox": {
    "width": 1200,
    "height": 900
  },
  "projection": {
    "type": "WebMercator",
    "minMercY": -0.543570654506458,
    "maxMercY": -0.5425661113788312,
    "description": "x = ((lon - west) / (east - west)) * width; y = height - ((mercY - minMercY) / (maxMercY - minMercY)) * height"
  }
};

// Função de projeção geográfica direta (WGS84 lat/lon -> SVG viewBox)
// Mantém as proporções exatas de Santa Maria - RS para alinhamento da futura rota
export function geoToSvg(lat: number, lon: number): [number, number] {
  const { bbox, viewBox, projection } = SANTA_MARIA_METADATA;
  const x = ((lon - bbox.west) / (bbox.east - bbox.west)) * viewBox.width;
  const latRad = (lat * Math.PI) / 180;
  const mercY = Math.log(Math.tan(Math.PI / 4 + latRad / 2));
  const y = viewBox.height - ((mercY - projection.minMercY) / (projection.maxMercY - projection.minMercY)) * viewBox.height;
  return [Number(x.toFixed(1)), Number(y.toFixed(1))];
}

export function svgToGeo(x: number, y: number): [number, number] {
  const { bbox, viewBox, projection } = SANTA_MARIA_METADATA;
  const lon = bbox.west + (x / viewBox.width) * (bbox.east - bbox.west);
  const mercY = projection.maxMercY - (y / viewBox.height) * (projection.maxMercY - projection.minMercY);
  const latRad = 2 * (Math.atan(Math.exp(mercY)) - Math.PI / 4);
  const lat = (latRad * 180) / Math.PI;
  return [Number(lat.toFixed(6)), Number(lon.toFixed(6))];
}

